package checkpoint

import (
	"context"

	"github.com/go-git/go-git/v6"
)

// OpenOptions configures Open. The zero value uses the default committed-ref
// topology and attaches no blob fetcher.
type OpenOptions struct {
	// BlobFetcher is the CLI-level on-demand blob fetcher. The checkpoint
	// package cannot resolve it itself, so the CLI layer injects it here and
	// Open attaches it to the constructed store(s). nil leaves on-demand
	// fetching off.
	BlobFetcher BlobFetchFunc

	// Refs overrides the default committed-ref topology. A non-nil value wins,
	// e.g. attach pins reads to Primary via PrimaryAsRead().
	Refs *PersistentRefs
}

// Stores is the facade returned by Open: the persistent store plus the git-only
// ephemeral (shadow-branch) capability and resolved committed-ref topology.
type Stores struct {
	// Persistent is the committed store that serves permanent reads and writes.
	Persistent PersistentStore

	ephemeral EphemeralStore
	refs      PersistentRefs
}

// Open resolves the checkpoint storage topology and constructs the backing
// store. It keeps ref resolution and blob-fetcher wiring in one place.
//
//nolint:unparam // Callers treat store construction as fallible at this boundary; the git backend has no fallible setup today.
func Open(ctx context.Context, repo *git.Repository, opts OpenOptions) (*Stores, error) {
	refs := resolveOpenRefs(ctx, opts)
	store := NewGitStore(repo, refs)
	if opts.BlobFetcher != nil {
		store.SetBlobFetcher(opts.BlobFetcher)
	}
	return &Stores{
		Persistent: store,
		ephemeral:  newEphemeralStore(repo, refs),
		refs:       refs,
	}, nil
}

func resolveOpenRefs(ctx context.Context, opts OpenOptions) PersistentRefs {
	if opts.Refs != nil {
		return *opts.Refs
	}
	return ResolveRefs(ctx)
}

// Ephemeral returns the git-backed shadow-branch (temporary) store.
func (s *Stores) Ephemeral() EphemeralStore { return s.ephemeral }

// Refs returns the resolved committed-ref topology.
func (s *Stores) Refs() PersistentRefs { return s.refs }

package checkpoint

import (
	"fmt"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

var (
	_ PersistentStore = (*GitStore)(nil)
	_ AuthorReader    = (*GitStore)(nil)
	_ Writer          = (*GitStore)(nil)
	_ EphemeralStore  = (*ephemeralStore)(nil)
)

// GitStore is the committed (persistent) checkpoint store. Writes target
// refs.Primary; committed reads resolve against refs.Read. The temporary
// shadow-branch surface lives in ephemeralStore.
type GitStore struct {
	repo        *git.Repository
	refs        PersistentRefs
	blobFetcher BlobFetchFunc
}

// ephemeralStore is the git shadow-branch (temporary) checkpoint store. It is
// an independent type from GitStore; the two share only package-level helpers.
type ephemeralStore struct {
	repo *git.Repository
	refs PersistentRefs
}

// newEphemeralStore creates the shadow-branch store for the given repository
// and committed-metadata topology (it consults refs.Primary to recognize the
// committed branch when listing shadow branches).
func newEphemeralStore(repo *git.Repository, refs PersistentRefs) *ephemeralStore {
	return &ephemeralStore{repo: repo, refs: refs}
}

// NewEphemeralStore constructs the git shadow-branch (temporary) checkpoint
// store. Most callers reach it via Open(...).Ephemeral(); this direct
// constructor exists for benchmarks and tests that exercise the shadow-branch
// surface without the full facade.
func NewEphemeralStore(repo *git.Repository, refs PersistentRefs) EphemeralStore {
	return newEphemeralStore(repo, refs)
}

// NewGitStore creates a checkpoint store backed by the given git repository
// and committed-metadata topology. Pass DefaultV1Refs() for the v1-only default
// or ResolveRefs(ctx) in code paths that honor settings.
func NewGitStore(repo *git.Repository, refs PersistentRefs) *GitStore {
	return &GitStore{repo: repo, refs: refs}
}

// SetBlobFetcher configures the store to automatically fetch missing blobs
// on demand when reading from metadata trees.
func (s *GitStore) SetBlobFetcher(f BlobFetchFunc) {
	s.blobFetcher = f
}

// Repository returns the underlying git repository.
func (s *GitStore) Repository() *git.Repository {
	return s.repo
}

// Refs returns the committed-metadata topology the store was constructed with.
func (s *GitStore) Refs() PersistentRefs {
	return s.refs
}

// PersistentReadRef returns the ref that committed-checkpoint reads resolve against.
func (s *GitStore) PersistentReadRef() plumbing.ReferenceName {
	return s.refs.Read
}

func (s *GitStore) setPrimaryRef(hash plumbing.Hash) error {
	if err := s.repo.Storer.SetReference(plumbing.NewHashReference(s.refs.Primary, hash)); err != nil {
		return fmt.Errorf("set primary metadata ref %s to %s: %w", s.refs.Primary, hash, err)
	}
	return nil
}

package checkpoint

import (
	"context"
	"slices"

	"github.com/go-git/go-git/v6/plumbing"

	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// PersistentRefs is the committed-metadata ref topology.
type PersistentRefs struct {
	Primary plumbing.ReferenceName
	Read    plumbing.ReferenceName
	Push    []plumbing.ReferenceName
}

// DefaultV1Refs returns the v1-only topology.
func DefaultV1Refs() PersistentRefs {
	v1Branch := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	return PersistentRefs{
		Primary: v1Branch,
		Read:    v1Branch,
		Push:    []plumbing.ReferenceName{v1Branch},
	}
}

// PrimaryFetchableFromOrigin reports whether Primary has an origin-tracking shadow.
func (r PersistentRefs) PrimaryFetchableFromOrigin() bool {
	return r.Primary.IsBranch() && slices.Contains(r.Push, r.Primary)
}

// ReadBootstrappableFromOrigin reports whether reads can be bootstrapped from
// origin: true when reads target Primary and Primary is fetchable from origin.
func (r PersistentRefs) ReadBootstrappableFromOrigin() bool {
	return r.Read == r.Primary && r.PrimaryFetchableFromOrigin()
}

// PrimaryAsRead returns a copy of r with Read pinned to Primary.
func (r PersistentRefs) PrimaryAsRead() PersistentRefs {
	r.Read = r.Primary
	return r
}

// ResolveRefs returns the committed metadata topology.
func ResolveRefs(_ context.Context) PersistentRefs {
	return DefaultV1Refs()
}

