38	type tokensProfileSignalDefinition struct {
39		id    string
40		label string
41	}
42	
43	var tokensProfileSignalDefinitions = []tokensProfileSignalDefinition{
44		{id: "context-replay-hotspot", label: "Cache/context replay hotspot"},
45		{id: "api-call-amplification", label: "API call amplification"},
46		{id: "subagent-heavy", label: "Subagent-heavy sessions"},
47		{id: "missing-token-data", label: "Missing token data"},
48	}
