50	const tokensProfileUsageScopeCheckpointObserved = "checkpoint_observed"
51	
52	func newTokensGroupCmd() *cobra.Command {
53		cmd := &cobra.Command{
54			Use:    "tokens",
55			Short:  "Analyze token usage across sessions and checkpoints",
56			Hidden: true,
57			Long: `Analyze token usage across sessions and checkpoints.
58	
59	Commands:
60	  profile  Aggregate token usage across committed checkpoints
61	
62	Examples:
63	  entire tokens profile
64	  entire tokens profile --json`,
65			RunE: func(cmd *cobra.Command, _ []string) error {
66				return cmd.Help()
67			},
68		}
69	
70		cmd.AddCommand(newTokensProfileCmd())
71		return cmd
72	}
73	
74	func newTokensProfileCmd() *cobra.Command {
75		var jsonFlag bool
76		var limitFlag int
77		var allFlag bool
78	
79		cmd := &cobra.Command{
80			Use:   "profile",
81			Short: "Aggregate token usage and recommendations across checkpoint history",
82			Long: `Aggregate token usage and recommendations across committed checkpoint history.
83	
84	The profile reads committed checkpoint metadata only. It does not inspect
85	transcripts or source files, so it is deterministic and avoids adding token
86	cost while diagnosing token usage. By default it scans the latest 50 committed
87	checkpoints; use --limit or --all to change the scope.`,
88			Args: cobra.NoArgs,
89			RunE: func(cmd *cobra.Command, _ []string) error {
90				limit := limitFlag
91				if allFlag {
92					limit = 0
93				} else if limit <= 0 {
94					return errors.New("--limit must be positive unless --all is used")
95				}
96				return runTokensProfile(cmd.Context(), cmd, jsonFlag, limit)
97			},
98		}
99	
100		cmd.Flags().BoolVar(&jsonFlag, "json", false, "Output as JSON")
101		cmd.Flags().IntVar(&limitFlag, "limit", 50, "Maximum committed checkpoints to analyze")
102		cmd.Flags().BoolVar(&allFlag, "all", false, "Analyze all committed checkpoints")
103		cmd.MarkFlagsMutuallyExclusive("limit", "all")
104		return cmd
105	}
106	
107	func runTokensProfile(ctx context.Context, cmd *cobra.Command, jsonOutput bool, limit int) error {
108		repo, err := openRepository(ctx)
109		if err != nil {
110			cmd.SilenceUsage = true
111			fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository.")
112			return NewSilentError(err)
113		}
114		defer repo.Close()
115	
116		store := checkpoint.NewGitStore(repo, checkpoint.ResolveRefs(ctx))
117		store.SetBlobFetcher(FetchBlobsByHash)
118		infos, err := store.List(ctx)
119		if err != nil {
120			return fmt.Errorf("failed to list checkpoints: %w", err)
121		}
122	
123		report, err := buildTokensProfileReport(ctx, store, infos, limit)
124		if err != nil {
125			return err
126		}
127	
128		if jsonOutput {
129			return writeTokensProfileJSON(cmd.OutOrStdout(), report)
130		}
131		writeTokensProfileText(cmd.OutOrStdout(), report)
132		return nil
133	}
134	
135	func buildTokensProfileReport(ctx context.Context, store *checkpoint.GitStore, infos []checkpoint.CheckpointInfo, limit int) (tokensProfileReport, error) {
136		checkpointsAvailable := len(infos)
137		infos = limitTokensProfileCheckpoints(infos, limit)
138		report := tokensProfileReport{
139			Source:               "committed_checkpoints",
140			UsageScope:           tokensProfileUsageScopeCheckpointObserved,
141			CheckpointsAvailable: checkpointsAvailable,
142			CheckpointsAnalyzed:  len(infos),
143		}
144		signals := make(map[string]*tokensProfileSignal, len(tokensProfileSignalDefinitions))
145		var aggregate *agent.TokenUsage
146	
147		for _, info := range infos {
148			if err := ctx.Err(); err != nil {
149				return tokensProfileReport{}, err //nolint:wrapcheck // Propagating context cancellation.
150			}
151	
152			summary, err := store.Read(ctx, info.CheckpointID)
153			if err != nil {
154				return tokensProfileReport{}, fmt.Errorf("failed to read checkpoint %s: %w", info.CheckpointID, err)
155			}
156			if summary == nil {
157				report.MissingTokenData++
158				addTokensProfileSignal(signals, "missing-token-data", info.CheckpointID, report.CheckpointsAnalyzed)
159				continue
160			}
161	
162			usage, metadataReadWarning, err := tokensProfileCheckpointUsage(ctx, store, info.CheckpointID, summary)
163			if err != nil {
164				return tokensProfileReport{}, err
165			}
166			if metadataReadWarning {
167				report.MetadataReadWarnings++
168			}
169			tokens := buildSessionTokensUsage(usage)
170			if tokens == nil {
171				report.MissingTokenData++
172				addTokensProfileSignal(signals, "missing-token-data", info.CheckpointID, report.CheckpointsAnalyzed)
173				continue
174			}
175	
176			report.CheckpointsWithTokenData++
177			aggregate = addCheckpointTokenUsage(aggregate, usage)
178			addTokensProfileTokenSignals(signals, info.CheckpointID, tokens, report.CheckpointsAnalyzed)
179		}
180	
181		report.Tokens = buildSessionTokensUsage(aggregate)
182		report.Signals = orderedTokensProfileSignals(signals)
183		report.Recommendations = tokensProfileRecommendations(report)
184		report.Limitations = tokensProfileLimitations(report)
185		return report, nil
186	}
187	
188	func limitTokensProfileCheckpoints(infos []checkpoint.CheckpointInfo, limit int) []checkpoint.CheckpointInfo {
189		if limit <= 0 || len(infos) <= limit {
190			return infos
191		}
192		return infos[:limit]
193	}
194	
195	func tokensProfileCheckpointUsage(ctx context.Context, store *checkpoint.GitStore, checkpointID id.CheckpointID, summary *checkpoint.CheckpointSummary) (*agent.TokenUsage, bool, error) {
196		if summary == nil {
197			return nil, false, nil
198		}
199	
200		metas := make([]*checkpoint.Metadata, 0, len(summary.Sessions))
201		metadataReadWarning := false
202		for i := range len(summary.Sessions) {
203			meta, err := store.ReadSessionMetadata(ctx, checkpointID, i)
204			if err != nil {
205				if ctxErr := ctx.Err(); ctxErr != nil {
206					return nil, false, ctxErr //nolint:wrapcheck // Propagating context cancellation.
207				}
208				metadataReadWarning = true
209				continue
210			}
211			metas = append(metas, meta)
212		}
213		return checkpointTokenUsage(summary, metas, metadataReadWarning), metadataReadWarning, nil
214	}
215	
216	func addTokensProfileTokenSignals(signals map[string]*tokensProfileSignal, checkpointID id.CheckpointID, tokens *sessionTokensUsage, denominator int) {
217		if tokens == nil {
218			return
219		}
220		topLevelTotal := topLevelSessionTokenTotal(tokens)
221		if topLevelTotal > 0 && tokenPercent(tokens.CacheRead, topLevelTotal) >= recommendationHighCacheReadPercent {
222			addTokensProfileSignal(signals, "context-replay-hotspot", checkpointID, denominator)
223		}
224		if tokens.APICalls >= 20 {
225			addTokensProfileSignal(signals, "api-call-amplification", checkpointID, denominator)
226		}
227		if tokenShareAtLeastOneTenth(tokens.SubagentTotal, tokens.Total) {
228			addTokensProfileSignal(signals, "subagent-heavy", checkpointID, denominator)
229		}
230	}
231	
232	func addTokensProfileSignal(signals map[string]*tokensProfileSignal, signalID string, checkpointID id.CheckpointID, denominator int) {
233		signal := signals[signalID]
234		if signal == nil {
235			definition := tokensProfileSignalDefinitionFor(signalID)
236			signal = &tokensProfileSignal{
237				ID:    definition.id,
238				Label: definition.label,
239			}
240			signals[signalID] = signal
241		}
242		signal.Count++
243		if denominator > 0 {
244			signal.Percent = roundedPercent(signal.Count, denominator)
245		}
246		if checkpointID != "" {
247			signal.CheckpointIDs = append(signal.CheckpointIDs, checkpointID.String())
248		}
249	}
250	
251	func tokensProfileSignalDefinitionFor(signalID string) tokensProfileSignalDefinition {
252		for _, definition := range tokensProfileSignalDefinitions {
253			if definition.id == signalID {
254				return definition
255			}
256		}
257		return tokensProfileSignalDefinition{id: signalID, label: signalID}
258	}
259	
260	func orderedTokensProfileSignals(signals map[string]*tokensProfileSignal) []tokensProfileSignal {
261		ordered := make([]tokensProfileSignal, 0, len(signals))
262		for _, definition := range tokensProfileSignalDefinitions {
263			if signal := signals[definition.id]; signal != nil {
264				ordered = append(ordered, *signal)
265			}
266		}
267		return ordered
268	}
269	
270	func tokensProfileRecommendations(report tokensProfileReport) []sessionTokensRecommendation {
271		var recs []sessionTokensRecommendation
272	
273		if report.CheckpointsAnalyzed == 0 {
274			return []sessionTokensRecommendation{{
275				ID:       "no-checkpoints",
276				Severity: "low",
277				Message:  "Create checkpoints first; token profiling needs committed checkpoint metadata to identify patterns.",
278				Signals:  []string{"empty_checkpoint_history"},
279			}}
280		}
281	
282		if tokensProfileSignalCount(report.Signals, "context-replay-hotspot") > 0 ||
283			tokensProfileSignalCount(report.Signals, "api-call-amplification") > 0 {
284			recs = append(recs, sessionTokensRecommendation{
285				ID:       "search-before-reinvestigation",
286				Severity: "high",
287				Message:  "Use `entire search` for prior decisions/checkpoints before broad re-investigation.",
288				Signals:  []string{"cache_read_tokens", "api_call_count"},
289			})
290		}
291		if tokensProfileSignalCount(report.Signals, "api-call-amplification") > 0 {
292			recs = append(recs, sessionTokensRecommendation{
293				ID:       "batch-diagnostics",
294				Severity: "medium",
295				Message:  "Batch diagnostic reads around one narrowed hypothesis when API call amplification repeats.",
296				Signals:  []string{"api_call_count"},
297			})
298		}
299		if tokensProfileSignalCount(report.Signals, "context-replay-hotspot") > 0 {
300			recs = append(recs, sessionTokensRecommendation{
301				ID:       "preserve-then-compact",
302				Severity: "medium",
303				Message:  "Summarize useful findings before continuing large-context work; compact or restart only after preserving relevant context.",
304				Signals:  []string{"cache_read_tokens"},
305			})
306		}
307		if tokensProfileSignalCount(report.Signals, "subagent-heavy") > 0 {
308			recs = append(recs, sessionTokensRecommendation{
309				ID:       "scope-subagents",
310				Severity: "medium",
311				Message:  "Scope subagent tasks tightly with a narrow objective and expected output.",
312				Signals:  []string{"subagent_tokens"},
313			})
314		}
315		if report.MissingTokenData > 0 {
316			recs = append(recs, sessionTokensRecommendation{
317				ID:       "improve-token-coverage",
318				Severity: "low",
319				Message:  "Increase token coverage by using agents and checkpoints that report token usage.",
320				Signals:  []string{"missing_token_usage"},
321			})
322		}
323	
324		if len(recs) == 0 {
325			recs = append(recs, sessionTokensRecommendation{
326				ID:       "no-repeated-hotspots",
327				Severity: "low",
328				Message:  "No repeated token hotspots were visible in committed checkpoint metadata.",
329				Signals:  []string{"checkpoint_token_metadata"},
330			})
331		}
332		return recs
333	}
334	
335	func tokensProfileSignalCount(signals []tokensProfileSignal, signalID string) int {
336		for _, signal := range signals {
337			if signal.ID == signalID {
338				return signal.Count
339			}
340		}
341		return 0
342	}
343	
344	func tokensProfileLimitations(report tokensProfileReport) []string {
345		var limitations []string
346		if report.CheckpointsAvailable > report.CheckpointsAnalyzed {
347			limitations = append(limitations, fmt.Sprintf("Limited to latest %d of %d committed checkpoints; use --limit or --all to change scope.", report.CheckpointsAnalyzed, report.CheckpointsAvailable))
348		}
349		if report.CheckpointsAnalyzed == 0 {
350			limitations = append(limitations, "No committed checkpoints found.")
351		}
352		if report.MissingTokenData > 0 {
353			limitations = append(limitations, fmt.Sprintf("%d checkpoint%s did not include token usage.", report.MissingTokenData, tokenPluralSuffix(report.MissingTokenData)))
354		}
355		if report.MetadataReadWarnings > 0 {
356			limitations = append(limitations, fmt.Sprintf("%d checkpoint%s had incomplete session metadata; profile used root token summaries or readable sessions where available.", report.MetadataReadWarnings, tokenPluralSuffix(report.MetadataReadWarnings)))
357		}
358		if report.Tokens != nil {
359			limitations = append(limitations, "Token totals are summed from analyzed checkpoints and may include overlapping checkpoint history; treat them as checkpoint-observed volume, not guaranteed unique session spend.")
360		}
361		if report.CheckpointsAnalyzed > 0 {
362			limitations = append(limitations, "Tool-level search/read spend is not captured yet; this profile infers patterns from token totals, cache/context replay, API call counts, and subagent totals.")
363		}
364		return limitations
365	}
366	
367	func writeTokensProfileJSON(w io.Writer, report tokensProfileReport) error {
368		enc := json.NewEncoder(w)
369		enc.SetIndent("", "  ")
370		if err := enc.Encode(report); err != nil {
371			return fmt.Errorf("failed to encode token profile report: %w", err)
372		}
373		return nil
374	}
375	
376	func writeTokensProfileText(w io.Writer, report tokensProfileReport) {
377		fmt.Fprintln(w, "Token profile")
378		fmt.Fprintln(w)
379		fmt.Fprintf(w, "Source:               %s\n", report.Source)
380		fmt.Fprintf(w, "Checkpoints available: %d\n", report.CheckpointsAvailable)
381		fmt.Fprintf(w, "Checkpoints analyzed: %d\n", report.CheckpointsAnalyzed)
382		fmt.Fprintf(w, "With token data:      %d\n", report.CheckpointsWithTokenData)
383		fmt.Fprintf(w, "Missing token data:   %d\n", report.MissingTokenData)
384		if report.MetadataReadWarnings > 0 {
385			fmt.Fprintf(w, "Metadata warnings:    %d\n", report.MetadataReadWarnings)
386		}
387	
388		writeTokenUsageSectionWithTitle(w, "Checkpoint-observed token usage", report.Tokens)
389		writeTokensProfileSignals(w, report.Signals)
390		if len(report.Recommendations) > 0 {
391			writeTokenRecommendations(w, report.Recommendations)
392		}
393		writeTokenLimitations(w, report.Limitations)
394	}
395	
396	func writeTokensProfileSignals(w io.Writer, signals []tokensProfileSignal) {
397		if len(signals) == 0 {
398			return
399		}
400	
401		fmt.Fprintln(w)
402		fmt.Fprintln(w, "Repeated signals")
403		for _, signal := range signals {
404			fmt.Fprintf(w, "- %s: %d checkpoint%s", signal.Label, signal.Count, tokenPluralSuffix(signal.Count))
405			if signal.Percent > 0 {
406				fmt.Fprintf(w, " (%d%%)", signal.Percent)
407			}
408			fmt.Fprintln(w)
409		}
410	}
